import { vpsTerm, vpsTermPriceCents } from "./billing-terms";
import { extraDiskCentsAt } from "./extra-disk";

/**
 * What one renewal costs — the SINGLE definition, used by every path that quotes
 * or charges one: the automatic sweep in worker/billing.ts, the saved-card path,
 * the "Renew now" button, the server page and the deploy wizard's term cards.
 *
 * WHY IT LIVES IN ITS OWN FILE. It used to sit in lib/stripe-cards.ts, which
 * imports the Stripe SDK and (transitively) nodemailer. The moment a CLIENT
 * component — the deploy wizard — needed the renewal price, that import chain
 * dragged `nodemailer/lib/dkim` into the browser bundle and the build failed with
 * "Can't resolve 'fs'". The pricing rule is pure arithmetic and has no business
 * carrying a mail transport with it, so it lives here with only the two tiny
 * modules it genuinely needs. lib/stripe-cards.ts re-exports it, so no server-side
 * caller had to change.
 *
 * The rule this file exists to enforce: there is ONE renewal formula. Two
 * incidents in one day came from a second copy — first a button that hardcoded
 * "+30 days" and the monthly price while the action charged a full term ($8.99
 * shown, $97.09 taken), then the shared quote written to fix it, which computed
 * from `plan.priceCents` and so ignored `gamePlan` and would have billed a $4.99
 * game server at its $8.99 base plan. Do not add a second formula.
 */
export type RenewalCharge = {
  months: number;
  totalCents: number;
  /** The extra-root-disk portion, which gets its own invoice line. */
  extraDiskCents: number;
  extraDiskMonthlyCents: number;
  /** Human label for the invoice / receipt ("Nebula VPS" or the game plan name). */
  label: string;
};

export type PricedServer = {
  termMonths: number;
  extraDiskGB: number;
  plan: { name: string; priceCents: number };
  gamePlan: { name: string; priceCents: number; termMonths: number } | null;
  dedicatedIp: unknown | null;
};

export function renewalCharge(
  server: PricedServer,
  prices: { ipMonthlyCents: number; extraDiskPerGbCents: number },
): RenewalCharge {
  const isGame = !!server.gamePlan;
  const months = isGame ? server.gamePlan!.termMonths : vpsTerm(server.termMonths).months;
  // Extra root disk is billed EVERY cycle at the current per-GB price. Game plans
  // are a flat all-in price and never carry the add-on lines.
  const extraDiskMonthlyCents = isGame ? 0 : extraDiskCentsAt(server.extraDiskGB, prices.extraDiskPerGbCents);
  const extraDiskCents = extraDiskMonthlyCents * months;
  const totalCents = isGame
    ? server.gamePlan!.priceCents
    : vpsTermPriceCents(server.plan.priceCents, months) +
      // Bill the IP surcharge only when the server ACTUALLY holds a dedicated IP,
      // not off the intent flag — a NAT-fallback server must never be charged for
      // an IP it never received.
      (server.dedicatedIp ? prices.ipMonthlyCents * months : 0) +
      extraDiskCents;
  return {
    months,
    totalCents,
    extraDiskCents,
    extraDiskMonthlyCents,
    label: isGame ? server.gamePlan!.name : `${server.plan.name} VPS`,
  };
}

// Imported from the PURE module, never from ./stripe-cards: this file is reached
// by the deploy wizard, a client component, and stripe-cards pulls the Stripe SDK
// and nodemailer — which breaks the browser build with "Can't resolve 'fs'".
import { renewalCharge, type PricedServer } from "./renewal-charge";

/**
 * What "Renew now" costs and how long it buys — for the BUTTON that quotes it.
 *
 * This is a presentation wrapper over `renewalCharge` (lib/stripe-cards.ts) and
 * deliberately owns no arithmetic of its own. It exists only to add the duration
 * phrasing the UI needs.
 *
 * WHY IT IS A WRAPPER RATHER THAN A FORMULA.
 *
 * The original incident: the button read `Renew now (+30 days, $8.99)` and
 * charged **$97.09**, moving the expiry twelve months — the label hardcoded
 * "+30 days" and the plan's MONTHLY price while `renewNow` charged a full term.
 * The fix was to compute the quote and the charge in one place.
 *
 * The second incident, hours later and in this very file: that shared place was
 * written as fresh arithmetic over `plan.priceCents`, which silently ignored
 * `gamePlan`. A game server carries BOTH a base `planId` and a `gamePlanId`, and
 * it is sold at the game plan's flat price — `minecraft-mm8w85` was sold at
 * $4.99 while its base Starter plan is $8.99. So the new shared quote would have
 * charged a game-server owner **80% more than they agreed to** the moment they
 * pressed Renew now. `renewalCharge` had handled this correctly all along, and
 * the automatic renewal sweep in `worker/billing.ts` already used it.
 *
 * The lesson is the one this codebase keeps relearning: the danger was never a
 * wrong formula, it was a SECOND formula. So there is exactly one, it lives in
 * `renewalCharge`, and everything that quotes or charges a renewal goes through
 * it — the worker sweep, the card path, this button, and the server page.
 */
export type RenewalQuote = {
  /** Total charged, in cents. */
  totalCents: number;
  /** Months the expiry advances by. */
  months: number;
  /** Human label for the duration, e.g. "12 months" / "1 month". */
  durationLabel: string;
  /** What the customer is buying ("Starter VPS", or the game plan's name). */
  label: string;
};

export function renewalQuote(
  server: PricedServer,
  prices: { ipMonthlyCents: number; extraDiskPerGbCents: number },
): RenewalQuote {
  const charge = renewalCharge(server, prices);
  return {
    totalCents: charge.totalCents,
    months: charge.months,
    durationLabel: charge.months === 1 ? "1 month" : `${charge.months} months`,
    label: charge.label,
  };
}

/**
 * Shared per-server DISK EXPANSION core — the money path for growing a single
 * server's OWN root disk without touching its plan's CPU/RAM/price.
 *
 * Used by the wallet flow (lib/actions-disk.ts expandServerDisk) and by the
 * Stripe confirm route so a paid checkout can apply the expansion immediately.
 * Plain server module (NOT "use server") — same shape as lib/resize.ts, and it
 * deliberately mirrors that file line-for-line so the two money paths can never
 * drift apart.
 *
 * ─── GROWTH IS ONE-WAY ──────────────────────────────────────────────────────
 * There is no shrink counterpart to `applyDiskExpand`, and nothing here (or
 * anywhere else) ever decrements `Server.extraDiskGB`.
 *
 * ─── WHY THIS CANNOT DOUBLE-CHARGE ──────────────────────────────────────────
 *  1. `diskExpandQuote` is the ONLY place the prorated amount is computed, and
 *     both the wallet path and the Stripe-confirm path call it.
 *  2. The wallet is debited exactly once, inside the same $transaction that
 *     creates the DISK_EXPAND job — a rolled-back debit leaves no job, and a
 *     job that exists was always paid for.
 *  3. On the card path the wallet is NOT touched until Stripe clears: checkout
 *     charges only the card remainder, the confirm route credits that remainder
 *     to the wallet and then debits the FULL proration, so the two net out.
 *  4. `creditCheckoutSession`'s UNIQUE(stripeSessionId) makes the confirm route
 *     idempotent — a reloaded/replayed confirm URL credits (and therefore
 *     applies) nothing a second time.
 *  5. `Server.extraDiskGB` is advanced by the WORKER on success, never here, so
 *     a failed expansion is refunded by the worker's reconcile pass and the
 *     customer never renews on storage they didn't get.
 */
import { db } from "./db";
import { debitWallet, InsufficientBalanceError } from "./wallet";
import { invoiceCreateData } from "./invoices";
import { getSettingInt } from "./settings";
import { diskCapacityCheck } from "./capacity";
import { remainingMonths } from "./proration";
import {
  EXTRA_DISK_DEFAULT_PER_GB_CENTS,
  EXTRA_DISK_MAX_TOTAL_GB,
  EXTRA_DISK_MIN_GB,
  EXTRA_DISK_STEP_GB,
  effectiveDiskGB,
  extraDiskCentsAt,
  extraDiskLabel,
  extraDiskProrateCents,
  isValidExtraDiskAddGB,
} from "./extra-disk";

export class DiskExpandError extends Error {}

/**
 * The per-GB/month price actually charged, from the admin setting
 * (`extra_disk_gb_price_cents`, default 10 = $0.10/GB/mo). Single source of
 * truth for every order/expansion/renewal/display path so they can't disagree.
 */
export async function extraDiskPerGbCents(): Promise<number> {
  const v = await getSettingInt("extra_disk_gb_price_cents", EXTRA_DISK_DEFAULT_PER_GB_CENTS);
  return Math.max(0, Math.round(v));
}

/** Monthly charge (integer cents) for `gb` GB of extra disk at the current price. */
export async function extraDiskMonthlyCents(gb: number): Promise<number> {
  if (!gb || gb <= 0) return 0;
  return extraDiskCentsAt(gb, await extraDiskPerGbCents());
}

type QuotedServer = NonNullable<Awaited<ReturnType<typeof loadServer>>>;

function loadServer(serverId: string) {
  return db.server.findUnique({ where: { id: serverId }, include: { plan: true } });
}

export type DiskExpandQuote = {
  server: QuotedServer;
  /** GB being added in THIS purchase. */
  addGB: number;
  /** `extraDiskGB` the server will hold once the worker finishes. */
  targetExtraDiskGB: number;
  /** Effective disk (plan + extra) after the expansion. */
  newTotalDiskGB: number;
  perGbCents: number;
  /** Recurring monthly cost of the newly-added GB (billed every renewal). */
  monthlyCents: number;
  /** One-off charge for the remainder of the CURRENT paid term. */
  prorateCents: number;
};

/**
 * Validate an expansion and compute the prorated charge over the ACTUAL
 * remaining duration — identical maths to `resizeQuote` (monthly cost × every
 * remaining month; null expiresAt on free/admin servers => 0). Throws
 * DiskExpandError with a user-facing message on any guard failure. Does NOT
 * check ownership — callers must do that.
 */
export async function diskExpandQuote(serverId: string, addGB: number): Promise<DiskExpandQuote> {
  const server = await loadServer(serverId);
  if (!server) throw new DiskExpandError("Not found");
  if (!isValidExtraDiskAddGB(addGB)) {
    throw new DiskExpandError(
      `Choose between ${EXTRA_DISK_MIN_GB} and 500 GB, in ${EXTRA_DISK_STEP_GB} GB steps.`,
    );
  }
  if (!["RUNNING", "STOPPED"].includes(server.status)) {
    throw new DiskExpandError("Server is busy — wait for the current operation to finish.");
  }
  if (!server.vmid) throw new DiskExpandError("This server hasn't finished provisioning yet.");

  const targetExtraDiskGB = server.extraDiskGB + addGB;
  const newTotalDiskGB = effectiveDiskGB(server.plan.diskGB, targetExtraDiskGB);
  if (newTotalDiskGB > EXTRA_DISK_MAX_TOTAL_GB) {
    throw new DiskExpandError(
      `A server's disk tops out at ${EXTRA_DISK_MAX_TOTAL_GB} GB — this would take it to ${newTotalDiskGB} GB. Contact support for larger volumes.`,
    );
  }

  // Don't sell space the node can't physically back.
  const cap = await diskCapacityCheck(server.nodeId, addGB);
  if (!cap.ok) throw new DiskExpandError(cap.reason ?? "Not enough storage available right now.");

  const perGbCents = await extraDiskPerGbCents();
  const monthlyCents = extraDiskCentsAt(addGB, perGbCents);

  // The remaining-term maths comes from the two SHARED functions the "Add storage"
  // control also calls, so the figure the customer agreed to and the figure debited
  // here cannot be two different derivations of the same idea. This block used to
  // inline both — its own `remainingMonths` expression over a second copy of
  // `MS_PER_AVG_MONTH` re-exported from lib/resize.ts.
  let prorateCents = 0;
  if (!server.isFree && server.expiresAt) {
    prorateCents = extraDiskProrateCents(monthlyCents, remainingMonths(server.expiresAt, Date.now()));
  }
  return { server, addGB, targetExtraDiskGB, newTotalDiskGB, perGbCents, monthlyCents, prorateCents };
}

/**
 * Apply the expansion: (optionally) debit the wallet for the prorated charge,
 * record the wallet transaction + PAID invoice, and queue the DISK_EXPAND job the
 * worker performs on Proxmox + inside the guest. Re-validates every guard (size,
 * ceiling, steady state, one in-flight job) so it is safe to call from the
 * unauthenticated confirm route. Throws DiskExpandError on any guard failure.
 *
 * `chargeCents` overrides the recomputed proration — the paid path passes the
 * exact amount the customer paid into their wallet at checkout so the debit here
 * nets to zero against that credit (mirrors lib/resize.ts applyResize).
 *
 * NOTE: `Server.extraDiskGB` is deliberately NOT advanced here. The worker sets it
 * only after the disk really grew, so a failed job is refunded (see
 * reconcileFailedJob) and no renewal ever bills for space that wasn't delivered.
 */
export async function applyDiskExpand(opts: {
  serverId: string;
  addGB: number;
  actorUserId: string;
  chargeCents?: number;
}): Promise<void> {
  const quote = await diskExpandQuote(opts.serverId, opts.addGB);
  const { server, addGB, targetExtraDiskGB, newTotalDiskGB, monthlyCents } = quote;
  const prorateCents = opts.chargeCents ?? quote.prorateCents;

  const pending = await db.job.count({
    where: { serverId: server.id, status: { in: ["QUEUED", "RUNNING"] } },
  });
  if (pending > 0) throw new DiskExpandError("Another operation is already in progress on this server.");

  const label = extraDiskLabel(addGB);
  try {
    await db.$transaction(async (tx) => {
      if (prorateCents > 0) {
        await debitWallet(tx, server.userId, prorateCents);
        await tx.walletTransaction.create({
          data: {
            userId: server.userId,
            amountCents: -prorateCents,
            description: `${label} (prorated) — ${server.hostname}`,
          },
        });
        // PAID invoice for the proration. The line item spells out BOTH the
        // permanence and the recurring monthly cost, so the billing document
        // itself carries the one-way warning.
        await tx.invoice.create({
          data: invoiceCreateData({
            userId: server.userId,
            description: `${label} (prorated) — ${server.hostname}`,
            status: "PAID",
            lineItems: [
              {
                description:
                  `${label} — prorated for remaining term (${server.hostname}). ` +
                  `Disk grows to ${newTotalDiskGB} GB permanently; renews at $${(monthlyCents / 100).toFixed(2)}/mo.`,
                qty: 1,
                unitCents: prorateCents,
                amountCents: prorateCents,
              },
            ],
          }),
        });
      }
      // Record the amount charged AND the target on the job so the worker can
      // (a) know how far to grow and (b) REVERSE the charge if the expansion
      // terminally fails — money is committed here, before the job runs.
      await tx.job.create({
        data: {
          type: "DISK_EXPAND",
          serverId: server.id,
          payload: { addGB, targetExtraDiskGB, prorateCents, monthlyCents } as any,
        },
      });
      await tx.auditLog.create({
        data: {
          userId: opts.actorUserId,
          action: "server.disk_expand",
          detail: `${server.id} +${addGB}GB -> extra=${targetExtraDiskGB} total=${newTotalDiskGB} prorate=${prorateCents}`,
        },
      });
    });
  } catch (e) {
    if (e instanceof InsufficientBalanceError) {
      throw new DiskExpandError("Insufficient balance — top up your wallet first.");
    }
    throw e;
  }
}

/**
 * Per-server extra disk — pure, dependency-free maths + copy.
 *
 * Deliberately has NO server-only imports (no db, no settings) so the exact same
 * module can be imported by client components (DeployWizard, AddStorage) and by
 * the server actions / worker. Whatever the customer SEES is byte-for-byte what
 * gets CHARGED — mirroring lib/wallet-split.ts.
 *
 * This is the server's OWN root disk growing, which is a different product from
 * block-storage volumes (lib/actions-volumes.ts): a volume is portable and can be
 * detached and deleted; this space is fused into the VM's root filesystem.
 *
 * ─── GROWTH IS ONE-WAY ──────────────────────────────────────────────────────
 * A live filesystem cannot be shrunk without risking data loss, and no serious
 * provider offers it. There is NO shrink path anywhere in the platform, and
 * `Server.extraDiskGB` is never decremented. Every surface that sells extra
 * storage must show EXTRA_DISK_ONE_WAY_NOTE before taking the money.
 */

/** Storage is sold in 10 GB increments — matches the slider/step in both UIs. */
export const EXTRA_DISK_STEP_GB = 10;
/** Smallest purchasable amount. */
export const EXTRA_DISK_MIN_GB = 10;
/** Largest amount purchasable in a SINGLE transaction. */
export const EXTRA_DISK_MAX_ADD_GB = 500;
/** Hard ceiling on a server's effective disk (plan.diskGB + extraDiskGB). */
export const EXTRA_DISK_MAX_TOTAL_GB = 2000;
/**
 * Fallback price per GB per month when the `extra_disk_gb_price_cents` admin
 * setting has never been written. 10 = $0.10/GB/mo, matching block storage.
 * Use `extraDiskMonthlyCents()` (lib/disk-expand.ts) in billing paths, never this.
 */
export const EXTRA_DISK_DEFAULT_PER_GB_CENTS = 10;

/** The one-way warning, shown verbatim on every surface that sells extra disk. */
export const EXTRA_DISK_ONE_WAY_NOTE =
  "Storage can only be added, never removed. Extra disk space is permanent for this server's lifetime and keeps billing every cycle.";

/** A server's EFFECTIVE root disk in GB — plan allowance plus purchased extra. */
export function effectiveDiskGB(planDiskGB: number, extraDiskGB: number | null | undefined): number {
  return Math.max(0, Math.round(planDiskGB)) + Math.max(0, Math.round(extraDiskGB ?? 0));
}

/**
 * Monthly cost (integer cents) of `gb` extra GB at `perGbCents`. Exact integer
 * multiplication — no floating-point money.
 */
export function extraDiskCentsAt(gb: number, perGbCents: number): number {
  const g = Math.max(0, Math.round(gb));
  const p = Math.max(0, Math.round(perGbCents));
  return g * p;
}

/**
 * The one-off charge for `monthlyCents` of extra disk over the months still left
 * on the current paid term. THE single definition, shared by the server
 * (lib/disk-expand.ts diskExpandQuote) and the control that DISPLAYS the figure
 * before the customer agrees to it (components/customer/AddStorage.tsx).
 *
 * It lives in this pure module for exactly the reason `walletSplit` does: the
 * client has to be able to import it, so what is shown is byte-for-byte what is
 * charged. Until 2026-07-27 the server computed
 * `Math.max(0, Math.round(monthlyCents * remainingMonths))` and AddStorage computed
 * the same expression over its OWN private copy of `MS_PER_AVG_MONTH` — the two
 * places agreeing by convention that this codebase has been bitten by repeatedly
 * (the wizard's promo line, the "+30 days" renew button, the resize picker before
 * it was moved onto lib/proration.ts). Pass `remainingMonths(expiresAt, now)` from
 * lib/proration.ts as the second argument; do not re-derive it.
 *
 * Clamped at both ends: an expired term (negative months) prorates to zero rather
 * than crediting, and a negative price can never come out as a negative charge.
 */
export function extraDiskProrateCents(monthlyCents: number, monthsRemaining: number): number {
  const monthly = Math.max(0, monthlyCents);
  const months = Math.max(0, monthsRemaining);
  if (!Number.isFinite(monthly) || !Number.isFinite(months)) return 0;
  return Math.max(0, Math.round(monthly * months));
}

/** Is `gb` a purchasable amount (a positive multiple of the step, within range)? */
export function isValidExtraDiskAddGB(gb: number): boolean {
  return (
    Number.isInteger(gb) &&
    gb >= EXTRA_DISK_MIN_GB &&
    gb <= EXTRA_DISK_MAX_ADD_GB &&
    gb % EXTRA_DISK_STEP_GB === 0
  );
}

/**
 * Coerce arbitrary input to a purchasable amount: rounded DOWN to the step and
 * clamped to [0, EXTRA_DISK_MAX_ADD_GB]. Rounding DOWN (never up) means a
 * malformed value can only ever cost the customer less, never more. Returns 0
 * for "no extra disk", which every caller treats as a no-op.
 */
export function normalizeExtraDiskGB(gb: unknown): number {
  const n = Number(gb);
  if (!Number.isFinite(n) || n <= 0) return 0;
  const stepped = Math.floor(n / EXTRA_DISK_STEP_GB) * EXTRA_DISK_STEP_GB;
  if (stepped < EXTRA_DISK_MIN_GB) return 0;
  return Math.min(EXTRA_DISK_MAX_ADD_GB, stepped);
}

/** Selectable amounts for the wizard/server-page controls: 10…500 GB by 10. */
export function extraDiskOptions(): number[] {
  const out: number[] = [];
  for (let g = EXTRA_DISK_MIN_GB; g <= EXTRA_DISK_MAX_ADD_GB; g += EXTRA_DISK_STEP_GB) out.push(g);
  return out;
}

/**
 * The largest amount a server can still add without breaching the effective-disk
 * ceiling, rounded DOWN to the step. 0 means "already at the ceiling".
 */
export function maxAddableExtraDiskGB(planDiskGB: number, extraDiskGB: number): number {
  const headroom = EXTRA_DISK_MAX_TOTAL_GB - effectiveDiskGB(planDiskGB, extraDiskGB);
  if (headroom < EXTRA_DISK_MIN_GB) return 0;
  return Math.min(EXTRA_DISK_MAX_ADD_GB, Math.floor(headroom / EXTRA_DISK_STEP_GB) * EXTRA_DISK_STEP_GB);
}

