/** Extract a plain OrderIntent from a deploy form. */
export function intentFromFormData(formData: FormData): OrderIntent {
  return {
    planId: String(formData.get("planId") ?? ""),
    osTemplateId: String(formData.get("osTemplateId") ?? ""),
    hostname: String(formData.get("hostname") ?? ""),
    nodeId: String(formData.get("nodeId") ?? "") || undefined,
    addonMalware: formData.get("addon_malware") === "1",
    addonBackup: formData.get("addon_backup") === "1",
    addonDocker: formData.get("addon_docker") === "1",
    termMonths: Number(formData.get("termMonths") ?? 1),
    dedicatedIp: formData.get("dedicatedIp") === "1",
    sshPublicKey: String(formData.get("sshPublicKey") ?? "").trim() || undefined,
    sshKeyName: String(formData.get("sshKeyName") ?? "deploy-key").slice(0, 60),
    free: formData.get("free") === "1",
    // Rounded DOWN to a purchasable step — a malformed value can only ever cost
    // the customer less, never more. Left UNDEFINED (not 0) when nothing was
    // bought so it drops out of JSON.stringify: the intent is round-tripped
    // through Stripe metadata, which is capped at 500 chars (lib/stripe.ts
    // createOrderCheckout), and every byte of headroom matters there.
    extraDiskGB: normalizeExtraDiskGB(formData.get("extraDiskGB")) || undefined,
    couponCode: String(formData.get("couponCode") ?? "").trim().toUpperCase() || undefined,
  };
}

/** Pick the least-committed enabled node (RAM headroom). Falls back to primary. */
async function scheduleNode(planRamMB: number) {
  const nodes = await db.node.findMany({ where: { enabled: true, status: "ONLINE" } });
  if (nodes.length === 0) return null;
  const loads = await Promise.all(
    nodes.map(async (n) => {
      const agg = await db.server.findMany({
        where: { nodeId: n.id, status: { notIn: ["DELETING"] } },
        select: { plan: { select: { ramMB: true } } },
      });
      const used = agg.reduce((s, r) => s + r.plan.ramMB, 0);
      return { node: n, free: n.capacityRamMB - used };
    }),
  );
  loads.sort((a, b) => b.free - a.free);
  return loads[0].node;
}

