/**
 * Backup frequency & retention TIERS — the single source of truth for what each
 * backup tier grants (retention count, cadence) and its customer-facing copy.
 *
 * PURE module (no db, no settings imports) for the same reason as lib/extra-disk.ts:
 * the exact same maths is imported by the CLIENT wizard/upsell card that DISPLAYS a
 * price and by the server action / worker that ENFORCES + CHARGES it, so whatever
 * the customer sees is byte-for-byte what gets charged. Price resolution (the admin
 * setting) lives in the server-only lib/backup-upgrade.ts, mirroring how
 * extra-disk's pure maths sits apart from disk-expand's getSettingInt reader.
 *
 * MVP scope: only FREE (included, keep 2, daily) and PLUS (paid, keep 7, daily) are
 * SELLABLE. PRO/PREMIUM are defined for forward-compatibility but NOT offered in the
 * funnel — selling them needs pricing + (Premium) off-node storage this slice omits.
 * The MVP keeps cadence DAILY for every tier; only retention is sold.
 */

export type BackupTier = "FREE" | "PLUS" | "PRO" | "PREMIUM";

/** Legacy hardcoded retention every VPS shipped with (was worker CUSTOMER_BACKUP_KEEP=2). */
export const BACKUP_FREE_KEEP = 2;
/** Plus retention: a full week of daily restore points. */
export const BACKUP_PLUS_KEEP = 7;

/** Fallback Plus price when the `backup_plus_price_cents` admin setting is unset: $2.99/mo. */
export const BACKUP_PLUS_DEFAULT_PRICE_CENTS = 299;

/** Baseline cadence — daily. The MVP keeps every tier daily; only retention is sold. */
export const BACKUP_DAILY_INTERVAL_HOURS = 24;

/** Tiers a customer can actually pick in the MVP funnel. */
export const SELLABLE_BACKUP_TIERS: BackupTier[] = ["FREE", "PLUS"];

export type BackupTierSpec = {
  tier: BackupTier;
  /** Retention: how many recent archives are kept before the oldest are pruned. */
  keep: number;
  /** Scheduled cadence in hours. Daily across the board in the MVP. */
  intervalHours: number;
  /** Off-node/offsite durable copy. Always false in the MVP (Premium-only, deferred). */
  offsite: boolean;
  /** Short customer-facing name. */
  label: string;
  /** One-line description of what the tier keeps. */
  blurb: string;
  /** Whether this tier is offered in the funnel today. */
  sellable: boolean;
};

/** The tier -> {keep, cadence, offsite, copy} mapping. The ONE place this is defined. */
export function backupTierSpec(tier: BackupTier): BackupTierSpec {
  switch (tier) {
    case "PLUS":
      return {
        tier,
        keep: BACKUP_PLUS_KEEP,
        intervalHours: BACKUP_DAILY_INTERVAL_HOURS,
        offsite: false,
        label: "Plus",
        blurb: `Keep the last ${BACKUP_PLUS_KEEP} daily backups — a full week of restore points.`,
        sellable: true,
      };
    case "PRO":
      return {
        tier,
        keep: 14,
        intervalHours: BACKUP_DAILY_INTERVAL_HOURS,
        offsite: false,
        label: "Pro",
        blurb: "Keep two weeks of daily restore points.",
        sellable: false,
      };
    case "PREMIUM":
      return {
        tier,
        keep: 30,
        intervalHours: BACKUP_DAILY_INTERVAL_HOURS,
        offsite: true,
        label: "Premium",
        blurb: "Keep a month of restore points with an off-node copy.",
        sellable: false,
      };
    case "FREE":
    default:
      return {
        tier: "FREE",
        keep: BACKUP_FREE_KEEP,
        intervalHours: BACKUP_DAILY_INTERVAL_HOURS,
        offsite: false,
        label: "Standard",
        blurb: `Keep the last ${BACKUP_FREE_KEEP} daily backups. Included free.`,
        sellable: true,
      };
  }
}

/** Coerce arbitrary input (form value / round-tripped JSON) to a known tier; unknown => FREE. */
export function normalizeBackupTier(v: unknown): BackupTier {
  return v === "PLUS" || v === "PRO" || v === "PREMIUM" ? v : "FREE";
}

/**
 * The retention count the worker enforces for a row: an explicit per-row override
 * (`backupKeep`) wins, else the tier default. The single definition the VPS backup
 * executor's prune step reads.
 */
export function resolveBackupKeep(tier: BackupTier, keepOverride: number | null | undefined): number {
  if (keepOverride != null && keepOverride > 0) return Math.round(keepOverride);
  return backupTierSpec(tier).keep;
}

/**
 * Monthly price (integer cents) of a tier given the admin-tunable Plus price. PURE
 * so the wizard preview, the order charge and the renewal charge all derive the
 * SAME number (the display===charge invariant). Only PLUS is paid in the MVP; every
 * other tier is $0 here (PRO/PREMIUM are not sold, FREE is included).
 */
export function backupTierMonthlyCents(tier: BackupTier, plusCents: number): number {
  const p = Math.max(0, Math.round(plusCents));
  return tier === "PLUS" ? p : 0;
}

/**
 * Mid-term BACKUP TIER upgrade — the money path for raising ONE server's backup
 * RETENTION tier (FREE keep 2 -> PLUS keep 7) without touching its plan.
 *
 * Deliberately mirrors lib/disk-expand.ts line-for-line so the two paid-upgrade
 * money paths cannot drift apart:
 *   - `backupUpgradeQuote` is the ONLY place the prorated amount is computed, and
 *     both the display (server page card) and the charge (applyBackupUpgrade) call
 *     it, so the figure shown === the figure debited.
 *   - `applyBackupUpgrade` debits the wallet and applies the tier inside ONE
 *     $transaction: a rolled-back debit leaves the tier unchanged, and a tier that
 *     was applied was always paid for. It re-checks the current tier INSIDE the tx
 *     before debiting, so a double-submit can never double-charge.
 *
 * Two deliberate differences from disk-expand:
 *   1. WALLET-ONLY in the MVP (no Stripe mid-term checkout route — deferred to the
 *      full build). A customer with no balance can still buy Plus on card at ORDER
 *      time through lib/order.ts.
 *   2. NO worker job. Unlike growing a disk, retention is just a column the next
 *      scheduled prune reads (worker/index.ts backupCreate), so the tier is applied
 *      inline and takes effect on the next backup — nothing to reconcile.
 *
 * UPGRADE-ONLY: there is no downgrade path (baseline FREE is never taken away and no
 * refund logic exists here). Game servers are REJECTED — renewalCharge prices a game
 * plan as flat all-in with NO add-on lines, so granting one a paid tier would sell a
 * tier the renewal engine never bills (the "never grant a paid tier without payment"
 * invariant, in reverse).
 */
import { db } from "./db";
import { debitWallet, InsufficientBalanceError } from "./wallet";
import { invoiceCreateData } from "./invoices";
import { getSettingInt } from "./settings";
import { remainingMonths } from "./proration";
import {
  type BackupTier,
  BACKUP_PLUS_DEFAULT_PRICE_CENTS,
  backupTierMonthlyCents,
  backupTierSpec,
} from "./backup-tiers";

export class BackupUpgradeError extends Error {}

/**
 * The Plus monthly price actually charged, from the admin setting
 * (`backup_plus_price_cents`, default 299 = $2.99/mo). Single source of truth for
 * the order-time upsell, this mid-term upgrade and every renewal, so they cannot
 * disagree.
 */
export async function backupPlusMonthlyCents(): Promise<number> {
  const v = await getSettingInt("backup_plus_price_cents", BACKUP_PLUS_DEFAULT_PRICE_CENTS);
  return Math.max(0, Math.round(v));
}

function loadServer(serverId: string) {
  return db.server.findUnique({ where: { id: serverId } });
}
type QuotedServer = NonNullable<Awaited<ReturnType<typeof loadServer>>>;

export type BackupUpgradeQuote = {
  server: QuotedServer;
  targetTier: BackupTier;
  /** Resolved retention the tier grants. */
  keep: number;
  /** Recurring monthly cost of the tier (billed every renewal). */
  monthlyCents: number;
  /** One-off charge for the remainder of the CURRENT paid term (0 for free/admin). */
  prorateCents: number;
};

/**
 * Validate an upgrade and compute the prorated charge over the ACTUAL remaining
 * term — identical maths to diskExpandQuote (monthly cost x every remaining month;
 * null expiresAt on free/admin servers => 0). Throws BackupUpgradeError on any guard
 * failure. Does NOT check ownership — callers must.
 */
export async function backupUpgradeQuote(
  serverId: string,
  targetTier: BackupTier,
): Promise<BackupUpgradeQuote> {
  const server = await loadServer(serverId);
  if (!server) throw new BackupUpgradeError("Not found");
  if (server.gamePlanId) {
    throw new BackupUpgradeError("Backup tiers aren't available for game servers yet.");
  }
  if (targetTier !== "PLUS") throw new BackupUpgradeError("That backup tier isn't available.");
  if (server.backupTier === targetTier) {
    throw new BackupUpgradeError("This server is already on that backup tier.");
  }
  if (!["RUNNING", "STOPPED"].includes(server.status)) {
    throw new BackupUpgradeError("Server is busy — wait for the current operation to finish.");
  }

  const spec = backupTierSpec(targetTier);
  const monthlyCents = backupTierMonthlyCents(targetTier, await backupPlusMonthlyCents());
  // Remaining-term maths from the SHARED lib/proration.ts helper (same as
  // extraDiskProrateCents) so the card's figure and this debit are one derivation.
  let prorateCents = 0;
  if (!server.isFree && server.expiresAt) {
    prorateCents = Math.max(0, Math.round(monthlyCents * remainingMonths(server.expiresAt, Date.now())));
  }
  return { server, targetTier, keep: spec.keep, monthlyCents, prorateCents };
}

/**
 * Apply the upgrade: (optionally) debit the wallet for the prorated charge, record
 * the wallet transaction + PAID invoice, and stamp the tier + resolved retention on
 * the server — all in ONE $transaction. `chargeCents` overrides the recomputed
 * proration for a caller that already collected an exact amount (parity with
 * applyDiskExpand, unused in the wallet-only MVP). Throws BackupUpgradeError on any
 * guard failure or insufficient balance.
 */
export async function applyBackupUpgrade(opts: {
  serverId: string;
  targetTier: BackupTier;
  actorUserId: string;
  chargeCents?: number;
}): Promise<void> {
  const quote = await backupUpgradeQuote(opts.serverId, opts.targetTier);
  const { server, targetTier, keep, monthlyCents } = quote;
  const prorateCents = opts.chargeCents ?? quote.prorateCents;
  const spec = backupTierSpec(targetTier);
  const label = `${spec.label} backups (keep ${keep})`;

  try {
    await db.$transaction(async (tx) => {
      // Re-read the tier INSIDE the tx before any money moves: two concurrent
      // upgrades (a double-click) both quote FREE, but only the first commits PLUS;
      // the second sees PLUS here and aborts before debiting — no double charge.
      const fresh = await tx.server.findUnique({
        where: { id: server.id },
        select: { backupTier: true, status: true },
      });
      if (!fresh) throw new BackupUpgradeError("Not found");
      if (fresh.backupTier === targetTier) {
        throw new BackupUpgradeError("This server is already on that backup tier.");
      }
      if (!["RUNNING", "STOPPED"].includes(fresh.status)) {
        throw new BackupUpgradeError("Server is busy — wait for the current operation to finish.");
      }

      if (prorateCents > 0) {
        await debitWallet(tx, server.userId, prorateCents);
        await tx.walletTransaction.create({
          data: {
            userId: server.userId,
            amountCents: -prorateCents,
            description: `${label} (prorated) — ${server.hostname}`,
          },
        });
        await tx.invoice.create({
          data: invoiceCreateData({
            userId: server.userId,
            description: `${label} (prorated) — ${server.hostname}`,
            status: "PAID",
            lineItems: [
              {
                description:
                  `${label} — prorated for remaining term (${server.hostname}). ` +
                  `Renews at $${(monthlyCents / 100).toFixed(2)}/mo.`,
                qty: 1,
                unitCents: prorateCents,
                amountCents: prorateCents,
              },
            ],
          }),
        });
      }
      // Apply the tier + resolved retention, and make sure backups actually RUN —
      // retention is meaningless without a schedule, so bridge to the columns the
      // scheduler (worker/backup-schedule.ts) reads, exactly as the order path does.
      await tx.server.update({
        where: { id: server.id },
        data: {
          backupTier: targetTier,
          backupKeep: keep,
          autoBackup: true,
          backupIntervalHours: spec.intervalHours,
        },
      });
      await tx.auditLog.create({
        data: {
          userId: opts.actorUserId,
          action: "server.backup_upgrade",
          detail: `${server.id} -> ${targetTier} keep=${keep} prorate=${prorateCents}`,
        },
      });
    });
  } catch (e) {
    if (e instanceof InsufficientBalanceError) {
      throw new BackupUpgradeError("Insufficient balance — top up your wallet first.");
    }
    throw e;
  }
}

