import { InsufficientBalanceError } from "./wallet";
import {
  backupUpgradeQuote,
  applyBackupUpgrade,
  BackupUpgradeError,
} from "./backup-upgrade";
import { normalizeBackupTier } from "./backup-tiers";
import { emailVerificationError } from "./email-verification";

/**
 * Post-deploy "Keep more restore points": raise ONE server's backup retention tier
 * (FREE -> PLUS) for the prorated remainder of its term.
 *
 * Money path is a carbon copy of lib/actions-disk.ts expandServerDisk, minus the
 * card leg: quote (the SAME `backupUpgradeQuote` the page displays) -> wallet check
 * -> applyBackupUpgrade (atomic debit + tier stamp). The wallet is only ever debited
 * inside applyBackupUpgrade's $transaction, so displayed === charged and nothing is
 * charged twice. Upgrade-only: there is no companion downgrade.
 */
async function ownedServer(serverId: string) {
  const user = await requireUser();
  const server = await db.server.findUnique({ where: { id: serverId } });
  if (!server) throw new Error("Not found");
  if (server.userId !== user.id && user.role !== "ADMIN") throw new Error("Forbidden");
  return { user, server };
}

export async function upgradeServerBackupTier(
  serverId: string,
  tier: string,
): Promise<{ error?: string; ok?: boolean }> {
  // Spend path: block wallet debits while an admin is impersonating.
  await assertNotImpersonating();
  const { user } = await ownedServer(serverId);

  const target = normalizeBackupTier(tier);
  if (target !== "PLUS") return { error: "That backup tier isn't available." };

  // Purchase gate: a backup upgrade is a real charge. See lib/email-verification.ts.
  const unverified = await emailVerificationError(user);
  if (unverified) return { error: unverified };

  // Validate + price (ownership already checked). Surfaces the friendly guard message.
  let quote;
  try {
    quote = await backupUpgradeQuote(serverId, target);
  } catch (e) {
    if (e instanceof BackupUpgradeError) return { error: e.message };
    throw e;
  }

  // Wallet-only in the MVP: reject up front with a clear number if the balance
  // can't cover the proration, rather than throwing an opaque insufficiency later.
  if (!quote.server.isFree && quote.prorateCents > user.balanceCents) {
    return {
      error:
        `Upgrading to Plus backups costs $${(quote.prorateCents / 100).toFixed(2)} for the rest of your term, ` +
        `and card payments aren't set up for this change yet — top up your wallet first.`,
    };
  }

  try {
    await applyBackupUpgrade({ serverId, targetTier: target, actorUserId: user.id });
  } catch (e) {
    if (e instanceof BackupUpgradeError) return { error: e.message };
    if (e instanceof InsufficientBalanceError) {
      return { error: "Insufficient balance — top up your wallet first." };
    }
    throw e;
  }
  revalidatePath(`/dashboard/servers/${serverId}`);
  return { ok: true };
}

