"use client";

import { useState, useTransition } from "react";
import { useRouter } from "next/navigation";
import { upgradeServerBackupTier } from "@/lib/actions-backup";
import { fmtMoney } from "@/components/ui/primitives";
import type { BackupTier } from "@/lib/backup-tiers";

/**
 * "Keep more restore points" — the post-purchase backup RETENTION upsell that sits
 * on the Backups tab (app/dashboard/servers/[id]/page.tsx).
 *
 * Free keeps the latest 2 daily backups; Plus keeps a full week (7). The prorated
 * charge for the remainder of the term is computed AUTHORITATIVELY on the server by
 * backupUpgradeQuote and passed in as `prorateCents`, so the figure shown here is
 * byte-for-byte the figure the action debits (upgradeServerBackupTier re-quotes and
 * charges through the same function). Wallet-only in the MVP.
 *
 * Upgrade-only: a server already on Plus (or higher) sees a confirmation, not a
 * downgrade control — baseline retention is never taken away.
 */
export function BackupTierUpsell({
  serverId,
  currentTier,
  plusMonthlyCents,
  prorateCents,
  freeKeep,
  plusKeep,
  disabled,
}: {
  serverId: string;
  currentTier: BackupTier;
  plusMonthlyCents: number;
  /** Prorated charge for the rest of the term, or null when the server is busy. */
  prorateCents: number | null;
  freeKeep: number;
  plusKeep: number;
  disabled?: boolean;
}) {
  const router = useRouter();
  const [error, setError] = useState<string | null>(null);
  const [pending, start] = useTransition();

  // Already on Plus (or a higher tier): nothing to sell, just confirm the coverage.
  if (currentTier !== "FREE") {
    return (
      <div className="card">
        <h2 className="font-semibold">Backup retention</h2>
        <p className="mt-1 text-sm text-slate-400">
          This server is on <span className="text-brand-300">Plus backups</span> — the last {plusKeep}{" "}
          daily backups are kept, a full week of restore points.
        </p>
      </div>
    );
  }

  function upgrade() {
    start(async () => {
      setError(null);
      const res = await upgradeServerBackupTier(serverId, "PLUS");
      if (res?.error) {
        setError(res.error);
      } else {
        router.refresh();
      }
    });
  }

  const proratedLabel =
    prorateCents == null
      ? null
      : prorateCents === 0
        ? "No charge for the rest of this term"
        : `${fmtMoney(prorateCents)} now for the rest of your term`;

  return (
    <div className="card space-y-4">
      <div>
        <h2 className="font-semibold">Keep more restore points</h2>
        <p className="mt-1 max-w-lg text-sm text-slate-400">
          You&apos;re on <span className="text-slate-200">Standard</span> retention — the latest{" "}
          {freeKeep} daily backups are kept. Upgrade to{" "}
          <span className="text-brand-300">Plus</span> to keep the last {plusKeep} (a full week of
          restore points) for <span className="text-slate-200">{fmtMoney(plusMonthlyCents)}/mo</span>.
        </p>
      </div>

      {error && (
        <div className="rounded-xl border border-red-500/30 bg-red-500/10 px-3 py-2 text-sm text-red-300">
          {error}
        </div>
      )}

      <div className="flex flex-wrap items-center justify-between gap-3">
        <div className="text-sm text-slate-400">
          {proratedLabel ?? "Wait for the current operation to finish to upgrade."}
          {proratedLabel && (
            <span className="block text-xs text-slate-500">
              Then {fmtMoney(plusMonthlyCents)}/mo, added to each renewal. Charged from your wallet.
            </span>
          )}
        </div>
        <button
          type="button"
          disabled={disabled || pending || prorateCents == null}
          onClick={upgrade}
          className="btn-primary shrink-0 disabled:opacity-50"
        >
          {pending ? "Upgrading…" : "Upgrade to Plus"}
        </button>
      </div>
    </div>
  );
}

